sys_script_include.script:
var ControlAssigmentsUtils = Class.create();
ControlAssigmentsUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    controlRegistration: function() {
        var basesToBeShown = [];
        var userID = this.getParameter("sysparm_user_id");

        var grAssign = new GlideRecord("x_1593183_bases_assignments");
        grAssign.addQuery("opened_by", userID);
        grAssign.addQuery("state", "3");
        grAssign.query();

        if (grAssign.next()) {
            return "true";
        }

        var grBase = new GlideRecord("x_1593183_bases_base");
        grBase.addQuery("max_capacity", "!=", 0);
        grBase.query();

        while (grBase.next()) {
            basesToBeShown.push(grBase.sys_id.toString());

        }



        return "sys_idIN" + basesToBeShown.join(",");



    },
    type: 'ControlAssigmentsUtils'
});
